// OrgAnalytics defines model for OrgAnalytics.
type OrgAnalytics struct {
	Auctions []struct {
		Bidders     int    `json:"bidders"`
		ClearingIdr int    `json:"clearingIdr"`
		Code        string `json:"code"`
		OpeningIdr  int    `json:"openingIdr"`
		Title       string `json:"title"`
	} `json:"auctions"`
	Categories []CategoryId `json:"categories"`

	// Demand Purchased quantity of the biggest item per month.
	Demand struct {
		Item   string `json:"item"`
		Points []struct {
			Month    string  `json:"month"`
			Quantity float64 `json:"quantity"`
			Requests int     `json:"requests"`
		} `json:"points"`
		Unit string `json:"unit"`
	} `json:"demand"`
	History []struct {
		CategoryId   CategoryId             `json:"categoryId"`
		Code         string                 `json:"code"`
		Item         string                 `json:"item"`
		Month        string                 `json:"month"`
		Quantity     Quantity               `json:"quantity"`
		Supplier     string                 `json:"supplier"`
		TotalIdr     int                    `json:"totalIdr"`
		UnitPriceIdr int                    `json:"unitPriceIdr"`
		Via          OrgAnalyticsHistoryVia `json:"via"`
	} `json:"history"`

	// PriceTrend Our unit price vs market for the biggest item, indexed to its first month = 100.
	PriceTrend struct {
		Item   string `json:"item"`
		Points []struct {
			Market float64 `json:"market"`
			Month  string  `json:"month"`
			Ours   float64 `json:"ours"`
		} `json:"points"`
	} `json:"priceTrend"`

	// Savings Paid vs budget vs market per month.
	Savings []struct {
		BudgetIdr int    `json:"budgetIdr"`
		MarketIdr int    `json:"marketIdr"`
		Month     string `json:"month"`
		SpendIdr  int    `json:"spendIdr"`
	} `json:"savings"`

	// Spend Spend per month per category (Rupiah), oldest first. Keys other than `month` are CategoryIds.
	Spend     []OrgAnalytics_Spend_Item `json:"spend"`
	Suppliers []struct {
		Id       string  `json:"id"`
		Name     string  `json:"name"`
		OnTime   float64 `json:"onTime"`
		Score    float64 `json:"score"`
		SpendIdr int     `json:"spendIdr"`
	} `json:"suppliers"`

	// UnitPrices Average unit price per item, ours vs market.
	UnitPrices []struct {
		AvgIdr    int    `json:"avgIdr"`
		Item      string `json:"item"`
		MarketIdr int    `json:"marketIdr"`
		Unit      string `json:"unit"`
	} `json:"unitPrices"`
}

